{
    QApplication a(argc, argv);

    int status = 0;
    status |= QTest::qExec(new UtilTests, argc, argv);
    status |= QTest::qExec(new PortExtensionTests, argc, argv);
    status |= QTest::qExec(new ParameterTests, argc, argv);
