7	void CalibrationTests::LinearDetection()
8	{
9	    // create some measurements
10	    std::vector<CalibrationMeasurement::Base*> m;
11	    double startFreq = 100000;
12	    double stopFreq = 6000000000;
13	    int points = 1001;
14	    Calibration cal;
15	    cal.getKit().setIdealDefault();
16	    auto open = new CalibrationMeasurement::Open(&cal);
17	    open->setPort(1);
18	    m.push_back(open);
19	    auto _short = new CalibrationMeasurement::Short(&cal);
20	    _short->setPort(1);
21	    m.push_back(_short);
22	    auto load = new CalibrationMeasurement::Load(&cal);
23	    load->setPort(1);
24	    m.push_back(load);
25	
26	    for(int i=0;i<points;i++) {
27	        double f = startFreq + (stopFreq - startFreq) * i / (points-1);
28	        DeviceDriver::VNAMeasurement meas;
29	        meas.frequency = f;
30	        meas.measurements["S11"] = 0.0;
31	        m[0]->addPoint(meas);
32	        m[1]->addPoint(meas);
33	        m[2]->addPoint(meas);
34	    }
35	
36	    // verify correct detection
37	    double detectedStart;
38	    double detectedStop;
39	    int detectedPoints;
40	    bool detectedLog;
41	    Calibration::hasFrequencyOverlap(m, &detectedStart, &detectedStop, &detectedPoints, &detectedLog);
42	
43	    QVERIFY(qFuzzyCompare(detectedStart, startFreq));
44	    QVERIFY(qFuzzyCompare(detectedStop, stopFreq));
45	    QVERIFY(detectedPoints == points);
46	    QVERIFY(detectedLog == false);
47	}
